+    private void persistData(List<Incident> incidents, List<Event> allEvents)
+        throws ServiceException {
+        // 初始状态：未诊断
+        incidents.forEach(incident -> incident.setDiagnosticStatus(DiagnosticStatusEnum.NOT_DIAGNOSED));
+        incidentDao.addIncident(incidents);
+
+        if (!allEvents.isEmpty()) {
+            incidentDao.addEvent(allEvents);
+        }
+
+        // 更新状态：待诊断
+        incidents.forEach(incident -> incident.setDiagnosticStatus(DiagnosticStatusEnum.PENDING_DIAGNOSIS));
+        incidentDao.addIncident(incidents);
+    }
+
+    /**
+     * 分发任务
+     *
+     * @param incidents 故障列表
+     * @throws ServiceException 服务异常
+     */
+    private void dispatchTasks(List<Incident> incidents)
+        throws ServiceException {
+        for (Incident incident : incidents) {
+            if (ALARM.equals(incident.getCategory())) {
+                handleAlarmTask(incident);
+            } else {
+                submitDiagnosisTask(incident);
             }
         }
     }

+    /**
+     * 处理单告警故障任务。
+     *
+     * @param incident 待加入延迟队列的故障对象
+     * @throws ServiceException 服务异常
+     */
+    private void handleAlarmTask(Incident incident)
+        throws ServiceException {
+        // 通过事务同步管理器注册回调函数，解决左右侧时间不一致导致的问题
+        if (TransactionSynchronizationManager.isSynchronizationActive()) {
+            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
+                @Override
+                public void afterCommit() {
+                    try {
+                        delayedIncidentScheduler.addIncidentWithDelay(incident);
+                    } catch (Exception e) {
+                        LOGGER.error("Failed to add incident to delay queue after commit, csn: {}",
+                            incident.getCsn(),
+                            e);
+                    }
+                }
+            });
+        } else {
+            delayedIncidentScheduler.addIncidentWithDelay(incident);
+        }
+    }
+
+    /**
+     * 提交异步诊断任务。 将故障交给线程池进行处理 捕获线程池拒绝策略等异常，做相应的降级处理。
+     *
+     * @param incident 待诊断的故障对象
+     * @throws ServiceException 服务异常
+     */
+    private void submitDiagnosisTask(Incident incident)
+        throws ServiceException {
+        try {
+            THREAD_POOL_EXECUTOR.execute(() -> {
+                incident.setDiagnosticStatus(DIAGNOSING);
+                try {
+                    incidentDao.addIncident(Collections.singletonList(incident));
+                    faultDiagnosis(incident);
+                    incidentDao.updateDiagnoseEndTime(incident.getCsn(), System.currentTimeMillis());
+                } catch (Exception e) {
+                    LOGGER.error("Error occurred during fault diagnosis:{}, incident csn {}", e, incident.getCsn());
+                }
+            });
+        } catch (RejectedExecutionException e) {
+            handleTaskSubmissionFailure(incident,
+                DiagnosticStatusEnum.RESOURCE_INSUFFICIENT_NOT_EXECUTED,
+                "RejectedExecutionException",
+                e.getMessage());
+        } catch (Exception e) {
+            handleTaskSubmissionFailure(incident,
+                DiagnosticStatusEnum.DIAGNOSIS_FAILED,
+                "addIncident exception",
+                e.getMessage());
+        }
+    }
+
+    /**
+     * 统一处理异步任务提交失败时的降级逻辑
+     *
