+     * @param status 要更新的失败状态 (如资源不足、诊断失败等)
+     * @param errorType 错误类型标识，用于日志记录
+     * @param errorMessage 具体的错误信息
+     * @throws ServiceException 服务异常
+     */
+    private void handleTaskSubmissionFailure(Incident incident, DiagnosticStatusEnum status, String errorType,
+        String errorMessage)
+        throws ServiceException {
+        incident.setDiagnosticStatus(status);
+        incidentDao.addIncident(Collections.singletonList(incident));
+        LOGGER.error("{} {}, incidentCsn {}", errorType, errorMessage, incident.getCsn());
+    }
